import { Meta, StoryObj } from "@storybook/react";
import { Banner, BannerProps, announcementTypes, arrowPositions, headingLevels, themingTypes } from "./banner";
import { action } from "storybook/actions";
import { expect, fn, userEvent, within } from "storybook/test";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

const buttonVariants = ["PrimaryButton", "SecondaryButton", "GhostButton", "OutlineButton"] satisfies Array<
  BannerProps["buttonVariant"]
>;

type StoryArgs = Omit<BannerProps, "onClose" | "onButtonClick"> & {
  hasCloseButton?: boolean;
};

/** Maps the story args to real Banner props: the boolean `hasCloseButton` control becomes
 * an `onClose` callback, and the action button renders whenever `buttonText` is set. */
const toBannerProps = ({ hasCloseButton, ...args }: StoryArgs): BannerProps => ({
  ...args,
  onClose: hasCloseButton ? () => action("Close button clicked")() : undefined,
  onButtonClick: args.buttonText ? () => action("Button clicked")() : undefined,
});

const meta: Meta<StoryArgs> = {
  title: "Primitives/Banner",
  component: Banner,
  parameters: {
    docs: {
      description: {
        component:
          "Highlighted message box with an icon, heading and optional paragraph, action button, close button " +
          "and extra children. The visual style follows the `type` prop (information, warning, darkWarning, " +
          "critical, success or inheritTheme), and an optional arrow can point the banner at surrounding " +
          "content. Besides `BannerProps` it also accepts all framer-motion div props, e.g. `animate` and " +
          "`initial`.",
      },
    },
  },
  argTypes: {
    id: { table: { disable: true } },
    "data-testid": { table: { disable: true } },
    type: { control: "select", options: themingTypes },
    headingLevel: { control: "select", options: headingLevels },
    arrow: { control: "select", options: [undefined, ...arrowPositions] },
    buttonVariant: { control: "select", options: buttonVariants },
    announcement: { control: "radio", options: announcementTypes },
    // Story-only control. The description has to live here: docgen only reads the component's
    // own props type, so jsdoc on StoryArgs would never reach the docs page.
    hasCloseButton: {
      control: "boolean",
      description: "Story-only control: renders the close button by supplying an `onClose` callback",
    },
  },
  args: {
    type: "information",
    heading: "Informationsruta",
    headingLevel: "h2",
    paragraph:
      "På din valda dag är det konsert. Om du köper entrébiljett den här dagen måste du gå in i parken innan 18:00.",
    id: "my-banner",
    border: false,
    arrow: undefined,
    buttonText: "",
    buttonVariant: "OutlineButton",
    center: false,
    hideIcon: false,
    announcement: "off",
    hasCloseButton: false,
  },
  render: (args) => <Banner {...toBannerProps(args)} />,
};

export default meta;

type Story = StoryObj<StoryArgs>;

