const onCloseSpy = fn();

export const TestCloseButton: Story = {
  args: {
    heading: "Can be closed",
  },
  render: (args) => <Banner {...toBannerProps(args)} onClose={onCloseSpy} />,
  play: async ({ canvasElement }) => {
    onCloseSpy.mockClear();
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByRole("button"));
    await expect(onCloseSpy).toHaveBeenCalledTimes(1);
  },
  parameters: {
    // The play function verifies the close-button wiring; closing does not change the
    // banner's own appearance, so the end state doesn't need a snapshot.
    chromatic: { disableSnapshot: true },
  },
};
